import { internationalization } from '@intlayer/config/built';
import type {
  LocalesValues,
  LocalizedUrl,
  ResolvedDefaultLocale,
} from '@intlayer/types/module_augmentation';
import { checkIsURLAbsolute } from '../utils/checkIsURLAbsolute';
import { getDomainHostname, getDomainOrigin } from './domainUtils';
import { getLocalizedPath } from './getLocalizedPath';
import { type RoutingOptions, resolveRoutingConfig } from './getPrefix';

/**
 * Generate URL by prefixing the given URL with the referenced locale or adding search parameters
 * based on the routing mode. Handles both absolute and relative URLs appropriately.
 *
 * This function gets the locales, default locale, and routing mode from the configuration if not provided.
 *
 * The path itself is localized by {@link getLocalizedPath}; this function only
 * resolves the origin to put in front of it — the one of an absolute input, or
 * the domain mapped to the target locale.
 *
 * Example:
 *
 * ```ts
 *  // prefix-no-default mode
 *  getLocalizedUrl('/about', 'fr', { locales: ['en', 'fr'], defaultLocale: 'en', mode: 'prefix-no-default' });
 *  // Returns '/fr/about' for the French locale
 *  // Returns '/about' for the English locale (default)
 *
 *  // prefix-all mode
 *  getLocalizedUrl('/about', 'en', { locales: ['en', 'fr'], defaultLocale: 'en', mode: 'prefix-all' });
 *  // Returns '/en/about' for the English locale
 *  // Returns '/fr/about' for the French locale
 *
 *  // search-params mode
 *  getLocalizedUrl('/about', 'fr', { locales: ['en', 'fr'], defaultLocale: 'en', mode: 'search-params' });
 *  // Returns '/about?locale=fr' for the French locale
 *
 *  // no-prefix mode
 *  getLocalizedUrl('/about', 'fr', { locales: ['en', 'fr'], defaultLocale: 'en', mode: 'no-prefix' });
 *  // Returns '/about' for any locale
 * ```
 *
 * @param url - The original URL string to be processed.
 * @param currentLocale - The current locale.
 * @param options - Configuration options
 * @param options.locales - Optional array of supported locales. Defaults to configured locales.
 * @param options.defaultLocale - The default locale. Defaults to configured default locale.
 * @param options.mode - URL routing mode for locale handling. Defaults to configured mode.
 * @param options.currentDomain - Hostname of the page being rendered. Used to decide
 *   whether to emit a relative URL (same domain) or an absolute URL (cross-domain).
 *   Auto-detected from the input URL or `window.location` when omitted.
 * @returns The localized URL for the current locale.
 */
/**
 * The return type is narrowed to a template-literal type when both `url` and
 * `currentLocale` are string literals and the routing mode / defaultLocale are
 * not overridden via `options`.
 */
export const getLocalizedUrl = <
  const T extends string,
  const L extends LocalesValues = ResolvedDefaultLocale,
>(
  url: T,
  currentLocale: L = internationalization?.defaultLocale as L,
  options: RoutingOptions = {}
): LocalizedUrl<T, L> => {
  const { domains, currentDomain } = resolveRoutingConfig(options);

  const isAbsoluteUrl = checkIsURLAbsolute(url);
  const parsedUrl = isAbsoluteUrl ? new URL(url) : new URL(url, 'http://e.com');

  // ── Domain routing ────────────────────────────────────────────────────────
  // Resolve the "current" hostname so we can choose between a relative URL
  // (same domain) and an absolute URL (cross-domain).
  //
  // Detection priority:
  //   1. Explicit `currentDomain` option passed by the caller.
  //   2. Hostname extracted from an absolute input URL.
  //   3. `window.location.hostname` in browser environments.
  // When none of these is available we fall back to generating an absolute
  // URL for domain-mapped locales (safe for SSR/static generation): the
  // locale prefix may already be stripped for domain-exclusive locales, so a
  // relative URL would silently point to the wrong locale on the current
  // domain.
  const detectedCurrentHostname =
    process.env.INTLAYER_ROUTING_DOMAINS !== 'false'
      ? getDomainHostname(
          currentDomain ??
            (isAbsoluteUrl ? parsedUrl.hostname : undefined) ??
            (typeof window !== 'undefined'
              ? window?.location?.hostname
              : undefined) ??
            ''
        ) || null
      : null;

  const localeDomain =
    process.env.INTLAYER_ROUTING_DOMAINS !== 'false'
      ? domains?.[currentLocale as LocalesValues]
      : undefined;

  const localeDomainHostname = localeDomain
    ? getDomainHostname(localeDomain)
    : null;

  // Prepend the locale's domain when it differs from the current hostname,
  // or when the current hostname is unknown (SSR without `currentDomain`).
  const isCrossDomain =
    localeDomainHostname !== null &&
    (detectedCurrentHostname === null ||
      localeDomainHostname !== detectedCurrentHostname);

  const normalizedDomain =
    isCrossDomain && localeDomain ? getDomainOrigin(localeDomain) : null;

  const baseUrl = normalizedDomain
    ? normalizedDomain
    : isAbsoluteUrl
      ? `${parsedUrl.protocol}//${parsedUrl.host}`
      : '';
  // ─────────────────────────────────────────────────────────────────────────

  const localizedPath = getLocalizedPath(
    `${parsedUrl.pathname}${parsedUrl.search}${parsedUrl.hash}`,
    currentLocale,
    options
  );

  return `${baseUrl}${localizedPath}` as LocalizedUrl<T, L>;
};
